BEGIN;
CREATE TEMP TABLE catalog_checks(name text, passed boolean);
DO $$
DECLARE seller uuid; other_seller uuid; published jsonb; first_product uuid; second_product uuid; foreign_product uuid; blue uuid; red uuid; cart jsonb; profile jsonb; reserved jsonb; oid uuid; paid jsonb; token text:=repeat('a',64); invalid_rejected boolean; old_stock integer;
BEGIN
 INSERT INTO public.sellers(user_id,store_username,store_name,ship_from_address) VALUES('TEST-catalog-'||gen_random_uuid(),'verify_cart_atomic','TEST catalog atomic',jsonb_build_object('fullName','TEST sender','phone','5555555555','street','TEST origin','city','Tlajomulco','state','JAL','postalCode','45640','country','MX')) RETURNING id INTO seller;
 INSERT INTO public.sellers(user_id,store_username,store_name) VALUES('TEST-other-'||gen_random_uuid(),'verify_cart_other','TEST other') RETURNING id INTO other_seller;
 published:=public.publish_catalog_product(seller,'{"title":"TEST Gorra","price":100,"stock":5,"currency":"MXN","images":[],"delivery_options":["meetup","shipping"],"catalog_visible":true,"weight_kg":1,"package_dimensions":{"length":20,"width":10,"height":5}}','[{"label":"Azul","stock":3,"price":150},{"label":"Roja","stock":2}]','TESTCART01');
 first_product:=(published->'product'->>'id')::uuid;
 SELECT id INTO blue FROM public.product_variants WHERE product_id=first_product AND label='Azul';
 SELECT id INTO red FROM public.product_variants WHERE product_id=first_product AND label='Roja';
 published:=public.publish_catalog_product(seller,'{"title":"TEST Camisa","price":50,"stock":2,"currency":"MXN","images":[],"delivery_options":["meetup","shipping"],"catalog_visible":true,"weight_kg":0.5,"package_dimensions":{"length":10,"width":10,"height":2}}','[]','TESTCART02');
 second_product:=(published->'product'->>'id')::uuid;
 published:=public.publish_catalog_product(other_seller,'{"title":"TEST Foreign","price":20,"stock":2,"currency":"MXN","images":[],"delivery_options":["meetup"],"catalog_visible":true}','[]','TESTCART03');
 foreign_product:=(published->'product'->>'id')::uuid;
 cart:=jsonb_build_array(jsonb_build_object('productId',first_product,'variantId',blue,'quantity',2,'price',0.01),jsonb_build_object('productId',second_product,'quantity',1));
 profile:=public.catalog_cart_profile('verify_cart_atomic',cart,'shipping');
 INSERT INTO catalog_checks VALUES('authoritative variant prices',(profile->>'subtotal')::numeric=350);
 INSERT INTO catalog_checks VALUES('aggregated package weight',(profile->'shippingProfile'->>'weightKg')::numeric=2.5);
 reserved:=public.reserve_catalog_purchase('verify_cart_atomic',cart,'RF-TESTC1',token,'TEST buyer','test@example.com','5555555555','{"street":"TEST destination","city":"TEST","postalCode":"45640","state":"JAL","country":"MX","fullName":"TEST","phone":"5555555555"}','meetup');
 oid:=(reserved->>'id')::uuid;
 INSERT INTO catalog_checks VALUES('one order with two lines',(SELECT count(*) FROM public.order_items WHERE order_id=oid)=2 AND (reserved->>'amount')::numeric=350);
 INSERT INTO catalog_checks VALUES('reserved variant stock',(SELECT stock FROM public.product_variants WHERE id=blue)=1 AND (SELECT stock FROM public.products WHERE id=first_product)=3);
 PERFORM public.cancel_unpaid_purchase(oid,'TEST cancellation'); PERFORM public.cancel_unpaid_purchase(oid,'TEST duplicate cancellation');
 INSERT INTO catalog_checks VALUES('restoration exactly once',(SELECT stock FROM public.product_variants WHERE id=blue)=3 AND (SELECT stock FROM public.products WHERE id=first_product)=5 AND (SELECT stock FROM public.products WHERE id=second_product)=2);
 invalid_rejected:=false;
 BEGIN PERFORM public.reserve_catalog_purchase('verify_cart_atomic',jsonb_build_array(jsonb_build_object('productId',first_product,'variantId',blue,'quantity',1),jsonb_build_object('productId',second_product,'quantity',20)),'RF-TESTC2',token,'TEST','test@example.com','555','{}','meetup'); EXCEPTION WHEN OTHERS THEN invalid_rejected:=true; END;
 INSERT INTO catalog_checks VALUES('no partial reserve on stock failure',invalid_rejected AND (SELECT stock FROM public.product_variants WHERE id=blue)=3 AND (SELECT count(*) FROM public.orders WHERE order_number='RF-TESTC2')=0);
 invalid_rejected:=false;
 BEGIN PERFORM public.catalog_cart_profile('verify_cart_atomic',jsonb_build_array(jsonb_build_object('productId',foreign_product,'quantity',1)), 'meetup'); EXCEPTION WHEN OTHERS THEN invalid_rejected:=true; END;
 INSERT INTO catalog_checks VALUES('foreign seller denied',invalid_rejected);
 invalid_rejected:=false;
 BEGIN PERFORM public.catalog_cart_profile('verify_cart_atomic',jsonb_build_array(jsonb_build_object('productId',first_product,'quantity',1)), 'meetup'); EXCEPTION WHEN OTHERS THEN invalid_rejected:=true; END;
 INSERT INTO catalog_checks VALUES('variant required',invalid_rejected);
 invalid_rejected:=false;
 BEGIN PERFORM public.reserve_purchase('TESTCART01','RF-TESTC3',token,'TEST','test@example.com','555','{}','meetup'); EXCEPTION WHEN OTHERS THEN invalid_rejected:=true; END;
 INSERT INTO catalog_checks VALUES('legacy variant bypass denied',invalid_rejected);
 reserved:=public.reserve_catalog_purchase('verify_cart_atomic',cart,'RF-TESTC4',token,'TEST','test@example.com','555','{}','meetup'); oid:=(reserved->>'id')::uuid;
 paid:=public.complete_payment_and_mark_order_paid(oid,'cs_test_catalog_fixture','pi_test_catalog_fixture',350,'MXN',NULL);
 INSERT INTO catalog_checks VALUES('atomic payment with multiple items',(paid->>'success')::boolean AND (SELECT payment_status::text FROM public.orders WHERE id=oid)='SUCCEEDED' AND (SELECT count(*) FROM public.payments WHERE order_id=oid)=1);
 PERFORM public.complete_payment_and_mark_order_paid(oid,'cs_test_catalog_fixture','pi_test_catalog_fixture',350,'MXN',NULL);
 INSERT INTO catalog_checks VALUES('duplicate payment leaves stock unchanged',(SELECT stock FROM public.product_variants WHERE id=blue)=1 AND (SELECT count(*) FROM public.payments WHERE order_id=oid)=1);
 INSERT INTO catalog_checks VALUES('paid order cannot release reserved stock',NOT public.cancel_unpaid_purchase(oid,'TEST invalid cancellation'));
 PERFORM public.set_catalog_variant_stock(seller,blue,4);
 INSERT INTO catalog_checks VALUES('variant restock updates product total',(SELECT stock FROM public.product_variants WHERE id=blue)=4 AND (SELECT stock FROM public.products WHERE id=first_product)=6);
 INSERT INTO catalog_checks VALUES('foreign seller cannot restock',public.set_catalog_variant_stock(other_seller,blue,10) IS NULL AND (SELECT stock FROM public.product_variants WHERE id=blue)=4);
 UPDATE public.products SET shipping_payer='buyer' WHERE id=first_product;
 invalid_rejected:=false;
 BEGIN PERFORM public.reserve_catalog_purchase('verify_cart_atomic',jsonb_build_array(jsonb_build_object('productId',first_product,'variantId',blue,'quantity',1)),'RF-TESTQUOTE',token,'TEST','test@example.com','555','{}','shipping'); EXCEPTION WHEN OTHERS THEN invalid_rejected:=true; END;
 INSERT INTO catalog_checks VALUES('shipping without valid quote never reserves',invalid_rejected AND (SELECT stock FROM public.product_variants WHERE id=blue)=4 AND (SELECT count(*) FROM public.orders WHERE order_number='RF-TESTQUOTE')=0);
 published:=public.publish_catalog_product(seller,'{"title":"TEST quick private catalog","price":90,"stock":1,"currency":"MXN","images":[],"delivery_options":["meetup"],"catalog_visible":false}','[]','TESTQUICK01');
 reserved:=public.reserve_purchase('TESTQUICK01','RF-TESTQUICK',token,'TEST','test@example.com','555','{}','meetup');
 INSERT INTO catalog_checks VALUES('quick link works outside catalog',(reserved->>'amount')::numeric=90 AND (SELECT stock FROM public.products WHERE id=(published->'product'->>'id')::uuid)=0);
 PERFORM public.cancel_unpaid_purchase((reserved->>'id')::uuid,'TEST cleanup');
 INSERT INTO catalog_checks VALUES('quick reservation still restores once',(SELECT stock FROM public.products WHERE id=(published->'product'->>'id')::uuid)=1);
 IF EXISTS(SELECT 1 FROM catalog_checks WHERE NOT passed) THEN RAISE EXCEPTION 'Catalog verification failed'; END IF;
END $$;
SELECT * FROM catalog_checks;
ROLLBACK;
